CREATE TABLE IF NOT EXISTS users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL UNIQUE CHECK(email=lower(email)),password_hash text NOT NULL,role text NOT NULL DEFAULT 'user' CHECK(role IN('user','admin')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS refresh_tokens(token_hash text PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,family_id uuid NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS refresh_family_idx ON refresh_tokens(family_id);
CREATE TABLE IF NOT EXISTS events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text NOT NULL UNIQUE,title text NOT NULL,category text NOT NULL,description text NOT NULL,venue text NOT NULL,city text NOT NULL,starts_at timestamptz NOT NULL,price integer NOT NULL CHECK(price>=0),capacity integer NOT NULL CHECK(capacity BETWEEN 1 AND 10000),image text NOT NULL DEFAULT 'concert',created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS events_city_date_idx ON events(city,starts_at);
CREATE INDEX IF NOT EXISTS events_category_date_idx ON events(category,starts_at);
CREATE INDEX IF NOT EXISTS events_search_idx ON events USING gin(to_tsvector('english',title||' '||description||' '||venue));
CREATE TABLE IF NOT EXISTS holds(id uuid PRIMARY KEY,event_id uuid NOT NULL REFERENCES events(id),user_id uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','consumed','released')),created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS holds_expiry_idx ON holds(expires_at) WHERE status='active';
CREATE TABLE IF NOT EXISTS orders(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id),event_id uuid NOT NULL REFERENCES events(id),hold_id uuid NOT NULL UNIQUE REFERENCES holds(id),idempotency_key text NOT NULL,request_hash text NOT NULL,amount integer NOT NULL CHECK(amount>=0),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','confirmed','refund_pending','refunded','failed')),payment_reference text UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,idempotency_key));
CREATE INDEX IF NOT EXISTS orders_user_created_idx ON orders(user_id,created_at DESC);
CREATE TABLE IF NOT EXISTS seats(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events(id),label text NOT NULL,price integer NOT NULL CHECK(price>=0),hold_id uuid REFERENCES holds(id),hold_expires_at timestamptz,order_id uuid REFERENCES orders(id),UNIQUE(event_id,label),CHECK((hold_id IS NULL)=(hold_expires_at IS NULL)));
CREATE INDEX IF NOT EXISTS seats_event_idx ON seats(event_id);
CREATE INDEX IF NOT EXISTS seats_order_idx ON seats(order_id) WHERE order_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS order_seats(order_id uuid NOT NULL REFERENCES orders(id),seat_id uuid NOT NULL REFERENCES seats(id),label text NOT NULL,PRIMARY KEY(order_id,seat_id));
CREATE TABLE IF NOT EXISTS tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id uuid NOT NULL REFERENCES orders(id),seat_id uuid NOT NULL REFERENCES seats(id),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id,seat_id));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_ticket_per_seat ON tickets(seat_id) WHERE active;
CREATE TABLE IF NOT EXISTS outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),kind text NOT NULL CHECK(kind IN('payment','email','refund')),aggregate_id uuid NOT NULL REFERENCES orders(id),published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(kind,aggregate_id));
CREATE INDEX IF NOT EXISTS outbox_unpublished_idx ON outbox(created_at) WHERE published_at IS NULL;
CREATE TABLE IF NOT EXISTS email_deliveries(order_id uuid NOT NULL REFERENCES orders(id),kind text NOT NULL,sent_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(order_id,kind));
CREATE TABLE IF NOT EXISTS payment_operations(order_id uuid NOT NULL REFERENCES orders(id),kind text NOT NULL CHECK(kind IN('charge','refund')),reference text NOT NULL UNIQUE,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(order_id,kind));
-- Marketplace v2. Append-only upgrade; existing v1 inventory remains intact.
CREATE TABLE IF NOT EXISTS market_accounts(id text PRIMARY KEY,email text NOT NULL UNIQUE,name text NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN('attendee','organiser')),organization text NOT NULL DEFAULT '',created_at text NOT NULL);
CREATE TABLE IF NOT EXISTS market_sessions(hash text PRIMARY KEY,user_id text NOT NULL REFERENCES market_accounts(id),expires_at bigint NOT NULL,kind text NOT NULL,family text NOT NULL,revoked integer NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS market_session_user ON market_sessions(user_id);
CREATE TABLE IF NOT EXISTS market_events(id text PRIMARY KEY,owner_id text NOT NULL,status text NOT NULL,starts_at text NOT NULL,city text NOT NULL,document text NOT NULL,inventory text NOT NULL,version integer NOT NULL DEFAULT 0,created_at text NOT NULL);
CREATE INDEX IF NOT EXISTS market_event_owner ON market_events(owner_id);
CREATE INDEX IF NOT EXISTS market_event_public ON market_events(status,starts_at);
CREATE TABLE IF NOT EXISTS market_orders(id text PRIMARY KEY,user_id text NOT NULL,event_id text NOT NULL REFERENCES market_events(id),status text NOT NULL,idempotency_key text NOT NULL,document text NOT NULL,version integer NOT NULL DEFAULT 0,created_at text NOT NULL,UNIQUE(user_id,idempotency_key));
CREATE INDEX IF NOT EXISTS market_order_event ON market_orders(event_id);
CREATE INDEX IF NOT EXISTS market_order_user ON market_orders(user_id,created_at);
CREATE TABLE IF NOT EXISTS market_rate_limits(key text PRIMARY KEY,count integer NOT NULL,expires_at bigint NOT NULL);
CREATE TABLE IF NOT EXISTS market_mutation_checks(id text PRIMARY KEY,ok integer NOT NULL CHECK(ok=1));
CREATE TABLE IF NOT EXISTS market_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),order_id text NOT NULL REFERENCES market_orders(id),kind text NOT NULL DEFAULT 'market-email',published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(order_id,kind));
CREATE TABLE IF NOT EXISTS market_email_deliveries(order_id text PRIMARY KEY REFERENCES market_orders(id),sent_at timestamptz NOT NULL DEFAULT now());
